#917E2C,\n    bug: #808D18,\n    ghost: #584578,\n    steel: #9999BC,\n    fire: #DD6510,\n    water: #3A6EEB,\n    grass: #549B31,\n    electric: color.shade(#FDD835, 5%),\n    psychic: color.shade(#F62765, 10%),\n    ice: color.shade(#73CACA, 10%),\n    dragon: #4D09F4,\n    dark: #41332A,\n    fairy: #E76D88,\n\n    // note: this one's special uwu\n    // (colors extracted from in-game Stellar type icon; will be used to populate gradient stops)\n    // (also... should've just made PokeType into an SVG in hindsight lmao)\n    stellar: (\n      #E4B637,\n      #FD7A33,\n      (#FA3E3A, topRight),\n      #E53B7D,\n      (#B762B1, middleRight),\n      #713CBE,\n      (#5E3B9D, bottomRight),\n      #374477,\n      #567D97,\n      #3599D5,\n      #21A5E0,\n      (#246FD4, bottomLeft),\n      #294FBC,\n      (#2C97C2, middleLeft),\n      (#16B345, topLeft),\n      #C7D86E,\n      #99A977,\n      // #B9864E,\n      #E0C08C,\n    ),\n  ),\n\n  adjustment: (\n    light: 8%, // shade (both highlight/non-highlight)\n    dark: 32%, // tint (for non-highlight only)\n\n    stellar: (\n      linear-angle: -30deg, // slanted right\n\n      // +% for tint, -% for shade\n      // (+/-% feature for stellar only)\n      color: (\n        light: -4%,\n        dark: 16%,\n      ),\n      background-color: (\n        light: 4%,\n        dark: -8%,\n      ),\n    ),\n  ),\n);\n\n$container: (\n  width: (\n    default: 36px,\n    sm: 28px,\n    xs: 22px,\n  ),\n\n  height: 13px,\n);\n\n$label: (\n  font-size: 8px,\n  border-radius: 5px,\n\n  text-shadow: (\n    default: 1px 1px 0 color.alpha(colors.$black, 0.1),\n    highlight: 1px 1px 0 color.alpha(colors.$black, 0.3),\n  ),\n\n  label-opacity: (\n    default: (\n      light: 0.75,\n      dark: 0.85,\n    ),\n\n    highlight: (\n      light: 1,\n      dark: 1,\n    ),\n  ),\n\n  // for the unknown/??? type\n  // (these colors were obtained with the commented out default background-opacity's below)\n  default-background-color: (\n    light: #DCDFE1,\n    dark: #2D2B2A,\n  ),\n\n  background-opacity: (\n    // for the unknown/??? type\n    default: (\n      light: 0.88,\n      dark: 0.88,\n    ),\n\n    highlight: (\n      light: 1,\n      dark: 1,\n    ),\n  ),\n);\n\n$tera-edge: (\n  size: (\n    edge: 6px,\n    middle: 7px,\n  ),\n\n  rotation: (\n    edge: 18deg, // must be positive (0deg is ok)\n    middle: 45deg,\n  ),\n\n  offset: (\n    edge: 1px, // must be positive (0 is ok)\n    middle: (\n      x: -2px,\n      y: 3px,\n    ),\n  ),\n\n  background-opacity: (\n    default: (\n      light: 0.9,\n      dark: 0.9,\n    ),\n\n    highlight: (\n      light: 1,\n      dark: 1,\n    ),\n  ),\n);\n\n.container {\n  position: relative;\n  display: inline-block;\n  width: map.get($container, width, default);\n  height: map.get($container, height);\n  @include transition.apply(width);\n\n  &.sm {\n    width: map.get($container, width, sm);\n  }\n\n  &.xs {\n    width: map.get($container, width, xs);\n  }\n}\n\n.label {\n  @include position.absolute-fill;\n  @include flex.row-center($inline: true);\n  @include font.apply(fonts.$mono);\n  font-size: map.get($label, font-size);\n  text-align: center;\n  text-transform: uppercase;\n  text-shadow: map.get($label, text-shadow, default);\n  border-radius: map.get($label, border-radius);\n  @include transition.apply(color, text-shadow, background-color);\n  user-select: none;\n  z-index: 1;\n\n  .light & {\n    color: color.alpha(map.get($types, default-color, light), map.get($label, label-opacity, default, light));\n    background-color: color.alpha(map.get($label, default-background-color, light), map.get($label, background-opacity, default, light));\n  }\n\n  .dark & {\n    color: color.alpha(map.get($types, default-color, dark), map.get($label, label-opacity, default, dark));\n    background-color: color.alpha(map.get($label, default-background-color, dark), map.get($label, background-opacity, default, dark));\n  }\n\n  // see `.highlight.light &` and `.highlight.dark &` in `.teraEdge` below\n  // for why we can't do `.highlight & { .light & { ... } ... }`\n  .highlight & {\n    text-shadow: map.get($label, text-shadow, highlight);\n  }\n\n  .highlight.light & {\n    color: color.alpha(colors.$white, map.get($label, label-opacity, highlight, light));\n    background-color: color.alpha(map.get($types, colors, unknown), map.get($label, background-opacity, default, light));\n  }\n\n  .highlight.dark & {\n    color: color.alpha(colors.$white, map.get($label, label-opacity, highlight, dark));\n    background-color: color.alpha(map.get($types, colors, unknown), map.get($label, background-opacity, default, dark));\n  }\n}\n\n.teraEdge {\n  display: inline-block;\n  width: map.get($tera-edge, size, edge);\n  height: map.get($tera-edge, size, edge);\n  @include transition.apply(background-color);\n  user-select: none;\n  pointer-events: none;\n\n  .light & {\n    background-color: color.alpha(map.get($label, default-background-color, light), map.get($tera-edge, background-opacity, default, light));\n  }\n\n  .dark & {\n    background-color: color.alpha(map.get($label, default-background-color, dark), map.get($tera-edge, background-opacity, default, dark));\n  }\n\n  // must be done this way btw (due to how I've nested the DOM elements lol)\n  // (one does not simply `.highlight & { .light & { ... } ... }` -> `.highlight .light .teraEdge`; should be `.highlight.light .teraEdge`)\n  .highlight.light & {\n    background-color: color.alpha(map.get($types, colors, unknown), map.get($label, background-opacity, default, light));\n  }\n\n  .highlight.dark & {\n    background-color: color.alpha(map.get($types, colors, unknown), map.get($label, background-opacity, default, dark));\n  }\n\n  &.topLeft {\n    @include position.absolute($top: map.get($tera-edge, offset, edge) * -1, $left: map.get($tera-edge, offset, edge));\n    transform: rotateZ(map.get($tera-edge, rotation, edge));\n  }\n\n  &.topRight {\n    @include position.absolute($top: map.get($tera-edge, offset, edge) * -1, $right: map.get($tera-edge, offset, edge));\n    transform: rotateZ(map.get($tera-edge, rotation, edge) * -1);\n  }\n\n  &.middleRight {\n    @include position.absolute($top: map.get($tera-edge, offset, middle, y), $right: map.get($tera-edge, offset, middle, x));\n    width: map.get($tera-edge, size, middle);\n    height: map.get($tera-edge, size, middle);\n    transform: rotateZ(map.get($tera-edge, rotation, middle));\n  }\n\n  &.bottomRight {\n    @include position.absolute($right: map.get($tera-edge, offset, edge), $bottom: map.get($tera-edge, offset, edge) * -1);\n    transform: rotateZ(map.get($tera-edge, rotation, edge));\n  }\n\n  &.bottomLeft {\n    @include position.absolute($bottom: map.get($tera-edge, offset, edge) * -1, $left: map.get($tera-edge, offset, edge));\n    transform: rotateZ(map.get($tera-edge, rotation, edge) * -1);\n  }\n\n  &.middleLeft {\n    @include position.absolute($top: map.get($tera-edge, offset, middle, y), $left: map.get($tera-edge, offset, middle, x));\n    width: map.get($tera-edge, size, middle);\n    height: map.get($tera-edge, size, middle);\n    transform: rotateZ(map.get($tera-edge, rotation, middle));\n  }\n}\n\n@each $type, $color in map.get($types, colors) {\n  @if $type != unknown {\n    $light-shade: map.get($types, adjustment, light);\n    $dark-tint: map.get($types, adjustment, dark);\n\n    .type-#{$type} {\n      @if $type == stellar {\n        $light-color-adj: map.get($types, adjustment, stellar, color, light);\n        $light-background-color-adj: map.get($types, adjustment, stellar, background-color, light);\n        $dark-color-adj: map.get($types, adjustment, stellar, color, dark);\n        $dark-background-color-adj: map.get($types, adjustment, stellar, background-color, dark);\n\n        // note: unless manipulated by any sass:map functions, meta.type-of() will return 'list' for `()`\n        // (not that it really matters here, but knowledge is power)\n        $light-colors: (); // list\n        $light-background-colors: (); // list\n        $light-tera-edges: (); // map\n        $dark-colors: (); // list\n        $dark-background-colors: (); // list\n        $dark-tera-edges: (); // map\n\n        @each $stop-tuple in $color {\n          $stop-color: if(meta.type-of($stop-tuple) == list, list.nth($stop-tuple, 1), $stop-tuple);\n          $tera-edge-name: if(meta.type-of($stop-tuple) == list, list.nth($stop-tuple, 2), null);\n\n          $light-stop-color: if($light-color-adj > 0, color.tint($stop-color, $light-color-adj), color.shade($stop-color, math.abs($light-color-adj)));\n          $light-stop-background-color: if($light-color-adj > 0, color.tint($stop-color, $light-background-color-adj), color.shade($stop-color, math.abs($light-background-color-adj)));\n          $dark-stop-color: if($dark-color-adj > 0, color.tint($stop-color, $dark-color-adj), color.shade($stop-color, math.abs($dark-color-adj)));\n          $dark-stop-background-color: if($dark-color-adj > 0, color.tint($stop-color, $dark-background-color-adj), color.shade($stop-color, math.abs($dark-background-color-adj)));\n\n          $light-colors: list.append($light-colors, $light-stop-color, $separator: comma);\n          $light-background-colors: list.append($light-background-colors, $light-stop-background-color, $separator: comma);\n          $dark-colors: list.append($dark-colors, $dark-stop-color, $separator: comma);\n          $dark-background-colors: list.append($dark-background-colors, $dark-stop-background-color, $separator: comma);\n\n          @if $tera-edge-name {\n            $light-tera-edges: map.set($light-tera-edges, $tera-edge-name, $light-stop-background-color);\n            $dark-tera-edges: map.set($dark-tera-edges, $tera-edge-name, $dark-stop-background-color);\n          }\n        }\n\n        &:not(.highlight) {\n          .label span {\n            color: colors.$transparent;\n            background-clip: text;\n          }\n\n          $linear-angle: map.get($types, adjustment, stellar, linear-angle);\n\n          &.light .label span {\n            background-image: linear-gradient($linear-angle, $light-colors);\n          }\n\n          &.dark .label span {\n            background-image: linear-gradient($linear-angle, $dark-colors);\n          }\n        }\n\n        &.highlight {\n          .label > span {\n            background-image: none;\n          }\n\n          &.light {\n            .label {\n              background-image: conic-gradient($light-background-colors);\n            }\n\n            @each $edge, $edge-color in $light-tera-edges {\n              .teraEdge.#{$edge} {\n                background-color: $edge-color;\n              }\n            }\n          }\n\n          &.dark {\n            .label {\n              background-image: conic-gradient($dark-background-colors);\n            }\n\n            @each $edge, $edge-color in $dark-tera-edges {\n              .teraEdge.#{$edge} {\n                background-color: $edge-color;\n              }\n            }\n          }\n        }\n      } @else {\n        $light-default-color: color.shade($color, $light-shade);\n        $dark-default-color: color.tint($color, $dark-tint);\n\n        &:not(.highlight) {\n          &.light .label {\n            color: color.alpha($light-default-color, map.get($label, label-opacity, default, light));\n          }\n\n          &.dark .label {\n            color: color.alpha($dark-default-color, map.get($label, label-opacity, default, dark));\n          }\n        }\n\n        $light-highlight-color: $light-default-color;\n        $dark-highlight-color: $color;\n\n        &.highlight {\n          &.light {\n            .label {\n              background-color: color.alpha($light-highlight-color, map.get($label, background-opacity, highlight, light));\n            }\n\n            .teraEdge {\n              background-color: color.alpha($light-highlight-color, map.get($tera-edge, background-opacity, highlight, light));\n            }\n          }\n\n          &.dark {\n            .label {\n              background-color: color.alpha($dark-highlight-color, map.get($label, background-opacity, highlight, dark));\n            }\n\n            .teraEdge {\n              background-color: color.alpha($dark-highlight-color, map.get($tera-edge, background-opacity, highlight, dark));\n            }\n          }\n        } // end &:not(.highlight), &.highlight\n      } // end @else\n    } // end .type-#{$type}\n  } // end @if\n}\n","////\n/// @group transition\n/// @author Keith Choison\n////\n\n@use 'sass:list';\n@use 'sass:meta';\n@use 'config/animations';\n\n@mixin apply($props...) {\n  $transitions: ();\n\n  @for $i from 1 through list.length($props) {\n    $prop: list.nth($props, $i);\n\n    $name: $prop;\n    $duration: animations.$transition-duration;\n    $function: animations.$transition-function;\n\n    @if meta.type-of($prop) == 'list' and list.length($prop) > 1 {\n      $name: list.nth($prop, 1);\n\n      @if list.nth($prop, 2) {\n        $duration: list.nth($prop, 2);\n      }\n\n      @if list.length($prop) > 2 and list.nth($prop, 3) {\n        $function: list.nth($prop, 3);\n      }\n    }\n\n    $transitions: list.append($transitions, '#{$name} #{$duration} #{$function}');\n  }\n\n  @if list.length($transitions) > 0 {\n    transition: #{list.zip($transitions)};\n  }\n}\n","////\n/// @group position\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n////\n\n@use 'sass:math';\n@use 'sass:meta';\n@use 'functions/list';\n\n///\n/// @access private\n///\n@mixin -inset(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @if $top {\n    top: $top;\n  }\n\n  @if $right {\n    right: $right;\n  }\n\n  @if $bottom {\n    bottom: $bottom;\n  }\n\n  @if $left {\n    left: $left;\n  }\n}\n\n@mixin inset(\n  $all: null,\n  $a: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $t: null,\n  $right: null,\n  $r: null,\n  $bottom: null,\n  $b: null,\n  $left: null,\n  $l: null,\n) {\n  @include -inset(\n    $top: if($top, $top, if($t, $t, if($y, $y, if($a, $a, $all)))),\n    $right: if($right, $right, if($r, $r, if($x, $x, if($a, $a, $all)))),\n    $bottom: if($bottom, $bottom, if($b, $b, if($y, $y, if($a, $a, $all)))),\n    $left: if($left, $left, if($l, $l, if($x, $x, if($a, $a, $all)))),\n  );\n}\n\n@mixin inset-all($all) {\n  @include inset($all: $all);\n}\n\n@mixin inset-none {\n  @include inset-all(0);\n}\n\n///\n/// @alias inset-none()\n///\n@mixin inset-0 {\n  @include inset-none;\n}\n\n@mixin inset-xy($x: null, $y: null) {\n  @include inset($x: $x, $y: $y);\n}\n\n@mixin inset-x($x) {\n  @include inset-xy($x: $x);\n}\n\n@mixin inset-x-none {\n  @include inset-x(0);\n}\n\n///\n/// @alias inset-x-none()\n///\n@mixin inset-x-0 {\n  @include inset-x-none;\n}\n\n@mixin inset-y($y) {\n  @include inset-xy($y: $y);\n}\n\n@mixin inset-y-none {\n  @include inset-y(0);\n}\n\n///\n/// @alias inset-y-none()\n///\n@mixin inset-y-0 {\n  @include inset-y-none;\n}\n\n@mixin top($top) {\n  @include inset($top: $top);\n}\n\n@mixin top-none {\n  @include top(0);\n}\n\n///\n/// @alias top-none()\n///\n@mixin top-0 {\n  @include top-none;\n}\n\n@mixin right($right) {\n  @include inset($right: $right);\n}\n\n@mixin right-none {\n  @include right(0);\n}\n\n///\n/// @alias right-none()\n///\n@mixin right-0 {\n  @include right-none;\n}\n\n@mixin bottom($bottom) {\n  @include inset($bottom: $bottom);\n}\n\n@mixin bottom-none {\n  @include bottom(0);\n}\n\n///\n/// @alias bottom-none()\n///\n@mixin bottom-0 {\n  @include bottom-none;\n}\n\n@mixin left($left) {\n  @include inset($left: $left);\n}\n\n@mixin left-none {\n  @include left(0);\n}\n\n///\n/// @alias left-none()\n///\n@mixin left-0 {\n  @include left-none;\n}\n\n@mixin unset-all {\n  @include inset-all(unset);\n}\n\n// translate\n\n@mixin translate(\n  $x: null,\n  $y: null,\n) {\n  @if meta.type-of($x) == 'number' or meta.type-of($y) == 'number' {\n    @if $x and $x != 0 and $y and $y != 0 {\n      transform: translate($x, $y);\n    } @else if $x and $x != 0 {\n      transform: translateX($x);\n    } @else if $y and $y != 0 {\n      transform: translateY($y);\n    }\n  }\n}\n\n///\n/// @access private\n///\n@mixin -position(\n  $position: relative,\n  $all: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @if not list.includes('relative' 'absolute' 'fixed' 'sticky', $position) {\n    @error 'Invalid $position value passed to the -position() mixin: #{$position}';\n  }\n\n  position: $position;\n  @include inset(\n    $all: $all,\n    $x: $x,\n    $y: $y,\n    $top: $top,\n    $right: $right,\n    $bottom: $bottom,\n    $left: $left,\n  );\n}\n\n// relative\n\n@mixin relative {\n  @include -position($position: relative);\n}\n\n///\n/// @alias relative()\n///\n@mixin rel {\n  @include relative;\n}\n\n// absolute\n\n@mixin absolute(\n  $all: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @include -position(\n    $position: absolute,\n    $all: $all,\n    $x: $x,\n    $y: $y,\n    $top: $top,\n    $right: $right,\n    $bottom: $bottom,\n    $left: $left,\n  );\n}\n\n///\n/// @alias absolute()\n///\n@mixin abs(\n  $a: null,\n  $x: null,\n  $y: null,\n  $t: null,\n  $r: null,\n  $b: null,\n  $l: null,\n) {\n  @include absolute(\n    $all: $a,\n    $x: $x,\n    $y: $y,\n    $top: $t,\n    $right: $r,\n    $bottom: $b,\n    $left: $l,\n  );\n}\n\n@mixin absolute-xy($x: null, $y: null) {\n  @include absolute($x: $x, $y: $y);\n}\n\n///\n/// @alias absolute-xy()\n///\n@mixin absolute-axis($horizontal: null, $vertical: null) {\n  @include absolute-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin absolute-all($margin) {\n  @include absolute($all: $margin);\n}\n\n///\n/// @alias absolute-all()\n///\n@mixin absolute-square($margin) {\n  @include absolute-all($margin);\n}\n\n@mixin absolute-fill {\n  @include absolute-all(0);\n}\n\n///\n/// @alias absolute-fill()\n///\n@mixin abs-fill {\n  @include absolute-fill;\n}\n\n@mixin absolute-0 {\n  @include absolute-fill;\n}\n\n///\n/// @alias absolute-0()\n///\n@mixin abs-0 {\n  @include absolute-0;\n}\n\n@mixin absolute-xy($x: null, $y: null) {\n  @include absolute($x: $x, $y: $y);\n}\n\n///\n/// @alias absolute-xy()\n///\n@mixin abs-xy($x: null, $y: null) {\n  @include absolute-xy($x: $x, $y: $y);\n}\n\n///\n/// @alias absolute-xy()\n///\n@mixin absolute-axis($vertical: null, $horizontal: null) {\n  @include absolute-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin absolute-x($x) {\n  @include absolute-xy($x: $x);\n}\n\n///\n/// @alias absolute-x()\n///\n@mixin abs-x($x) {\n  @include absolute-x($x);\n}\n\n@mixin absolute-y($y) {\n  @include absolute-xy($y: $y);\n}\n\n///\n/// @alias absolute-y()\n///\n@mixin abs-y($y) {\n  @include absolute-y($y);\n}\n\n@mixin absolute-anchor(\n  $x: null,\n  $y: null,\n  $x-prop: left,\n  $y-prop: top,\n) {\n  $translate-x: if($x, -$x, null);\n  $translate-y: if($y, -$y, null);\n\n  @if $translate-x and math.unit($translate-x) != '%' { // e.g., px\n    $translate-x: 0;\n  }\n\n  @if $translate-y and math.unit($translate-y) != '%' {\n    $translate-y: 0;\n  }\n\n  @include absolute(\n    $top: if($y-prop == top, $y, null),\n    $right: if($x-prop == right, $x, null),\n    $bottom: if($y-prop == bottom, $y, null),\n    $left: if($x-prop == left, $x, null),\n  );\n\n  @include translate($x: $translate-x, $y: $translate-y);\n}\n\n///\n/// @alias absolute-center()\n///\n@mixin abs-anchor(\n  $x: null,\n  $y: null,\n  $x-prop: left,\n  $y-prop: top,\n) {\n  @include absolute-anchor($x: $x, $y: $y, $x-prop: $x-prop, $y-prop: $y-prop);\n}\n\n@mixin absolute-center($x-prop: left, $y-prop: top) {\n  @include absolute-anchor($x: 50%, $y: 50%, $x-prop: $x-prop, $y-prop: $y-prop);\n}\n\n///\n/// @alias absolute-center()\n///\n@mixin abs-center($x-prop: left, $y-prop: top) {\n  @include absolute-center($x-prop: $x-prop, $y-prop: $y-prop);\n}\n\n// fixed\n\n@mixin fixed(\n  $all: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @include -position(\n    $position: fixed,\n    $all: $all,\n    $x: $x,\n    $y: $y,\n    $top: $top,\n    $right: $right,\n    $bottom: $bottom,\n    $left: $left,\n  );\n}\n\n@mixin fixed-xy($x: null, $y: null) {\n  @include fixed($x: $x, $y: $y);\n}\n\n///\n/// @alias fixed-xy()\n///\n@mixin fixed-axis($horizontal: null, $vertical: null) {\n  @include fixed-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin fixed-all($margin) {\n  @include fixed($all: $margin);\n}\n\n///\n/// @alias fixed-all()\n///\n@mixin fixed-square($margin) {\n  @include fixed-all($margin);\n}\n\n@mixin fixed-fill {\n  @include fixed-all(0);\n}\n\n///\n/// @alias fixed-fill()\n///\n@mixin fixed-0 {\n  @include fixed-fill;\n}\n\n@mixin fixed-x($x) {\n  @include fixed-xy($x: $x);\n}\n\n@mixin fixed-y($y) {\n  @include fixed-xy($y: $y);\n}\n\n@mixin fixed-anchor(\n  $x: null,\n  $y: null,\n  $x-prop: left,\n  $y-prop: top,\n) {\n  $translate-x: if($x, -$x, null);\n  $translate-y: if($y, -$y, null);\n\n  @if $translate-x and math.unit($translate-x) != '%' {\n    $translate-x: 0;\n  }\n\n  @if $translate-y and math.unit($translate-y) != '%' {\n    $translate-y: 0;\n  }\n\n  @include fixed(\n    $top: if($y-prop == top, $y, null),\n    $right: if($x-prop == right, $x, null),\n    $bottom: if($y-prop == bottom, $y, null),\n    $left: if($x-prop == left, $x, null),\n  );\n\n  @include translate($x: $translate-x, $y: $translate-y);\n}\n\n@mixin fixed-center($x-prop: left, $y-prop: top) {\n  @include fixed-anchor($x: 50%, $y: 50%, $x-prop: $x-prop, $y-prop: $y-prop);\n}\n\n// sticky\n\n@mixin sticky(\n  $all: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n  $t: null,\n  $r: null,\n  $b: null,\n  $l: null,\n) {\n  @include -position(\n    $position: sticky,\n    $all: $all,\n    $x: $x,\n    $y: $y,\n    $top: if($top, $top, $t),\n    $right: if($right, $right, $r),\n    $bottom: if($bottom, $bottom, $b),\n    $left: if($left, $left, $l),\n  );\n}\n\n@mixin sticky-all($all) {\n  @include sticky($all: $all);\n}\n\n@mixin sticky-fill {\n  @include sticky-all(0);\n}\n\n///\n/// @alias sticky-fill()\n///\n@mixin sticky-0 {\n  @include sticky-fill;\n}\n\n@mixin sticky-xy($x: null, $y: null) {\n  @include sticky($x: $x, $y: $y);\n}\n\n///\n/// @alias sticky-xy()\n///\n@mixin sticky-axis($vertical: null, $horizontal: null) {\n  @include sticky-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin sticky-x($x) {\n  @include sticky-xy($x: $x);\n}\n\n@mixin sticky-y($y) {\n  @include sticky-xy($y: $y);\n}\n","///\n/// @group flex\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n///\n\n///\n/// @access private\n///\n@mixin -flex(\n  $direction: null,\n  $justify: null,\n  $align: null,\n  $inline: false,\n) {\n  display: if($inline, inline-flex, flex);\n\n  @if $direction and $direction != row {\n    flex-direction: $direction;\n  }\n\n  @if $justify and $justify != flex-start {\n    justify-content: $justify;\n  }\n\n  @if $align and $align != stretch {\n    align-items: $align;\n  }\n}\n\n// rows\n\n@mixin row(\n  $justify: null,\n  $align: null,\n  $reverse: false,\n  $inline: false,\n) {\n  @include -flex(\n    if($reverse, row-reverse, row),\n    $justify,\n    $align,\n    $inline,\n  );\n}\n\n@mixin row-stretch($reverse: false, $inline: false) {\n  @include row(stretch, stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-stretch()\n///\n@mixin stretch($reverse: false, $inline: false) {\n  @include row-stretch($reverse, $inline);\n}\n\n@mixin row-start($align: center, $reverse: false, $inline: false) {\n  @include row(flex-start, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-start()\n///\n@mixin start($align: center, $reverse: false, $inline: false) {\n  @include row-start($align, $reverse, $inline);\n}\n\n@mixin row-start-stretch($reverse: false, $inline: false) {\n  @include row-start(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-start-stretch()\n///\n@mixin start-stretch($reverse: false, $inline: false) {\n  @include row-start-stretch($reverse, $inline);\n}\n\n@mixin row-center($align: center, $reverse: false, $inline: false) {\n  @include row(center, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-center()\n///\n@mixin center($align: center, $reverse: false, $inline: false) {\n  @include row-center($align, $reverse, $inline);\n}\n\n@mixin row-center-stretch($reverse: false, $inline: false) {\n  @include row-center(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-center-stretch()\n///\n@mixin center-stretch($reverse: false, $inline: false) {\n  @include row-center-stretch($reverse, $inline);\n}\n\n@mixin row-end($align: center, $reverse: false, $inline: false) {\n  @include row(flex-end, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-end()\n///\n@mixin end($align: center, $reverse: false, $inline: false) {\n  @include row-end($align, $reverse, $inline);\n}\n\n@mixin row-end-stretch($reverse: false, $inline: false) {\n  @include row-end(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-end-stretch()\n///\n@mixin end-stretch($reverse: false, $inline: false) {\n  @include row-end-stretch($reverse, $inline);\n}\n\n@mixin row-between($align: center, $reverse: false, $inline: false) {\n  @include row(space-between, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-between()\n///\n@mixin between($align: center, $reverse: false, $inline: false) {\n  @include row-between($align, $reverse, $inline);\n}\n\n@mixin row-between-stretch($reverse: false, $inline: false) {\n  @include row-between(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-between-stretch()\n///\n@mixin between-stretch($reverse: false, $inline: false) {\n  @include row-between-stretch($reverse, $inline);\n}\n\n@mixin row-around($align: center, $reverse: false, $inline: false) {\n  @include row(space-around, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-around()\n///\n@mixin around($align: center, $reverse: false, $inline: false) {\n  @include row-around($align, $reverse, $inline);\n}\n\n@mixin row-around-stretch($reverse: false, $inline: false) {\n  @include row-around(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-around-stretch()\n///\n@mixin around-stretch($reverse: false, $inline: false) {\n  @include row-around-stretch($reverse, $inline);\n}\n\n@mixin row-evenly($align: center, $reverse: false, $inline: false) {\n  @include row(space-evenly, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-evenly()\n///\n@mixin evenly($align: center, $reverse: false, $inline: false) {\n  @include row-evenly($align, $reverse, $inline);\n}\n\n@mixin row-evenly-stretch($reverse: false, $inline: false) {\n  @include row-evenly(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-evenly-stretch()\n///\n@mixin evenly-stretch($reverse: false, $inline: false) {\n  @include row-evenly-stretch($reverse, $inline);\n}\n\n// columns\n\n@mixin column(\n  $justify: null,\n  $align: null,\n  $reverse: false,\n  $inline: false,\n) {\n  @include -flex(\n    if($reverse, column-reverse, column),\n    $justify,\n    $align,\n    $inline,\n  );\n}\n\n///\n/// @alias column()\n///\n@mixin col(\n  $justify: null,\n  $align: null,\n  $reverse: false,\n  $inline: false,\n) {\n  @include column($justify, $align, $reverse, $inline);\n}\n\n@mixin column-stretch($reverse: false, $inline: false) {\n  @include column(stretch, stretch, $reverse, $inline);\n}\n\n///\n/// @alias column-stretch()\n///\n@mixin col-stretch($reverse: false, $inline: false) {\n  @include column-stretch($reverse, $inline);\n}\n\n@mixin column-start($align: center, $reverse: false, $inline: false) {\n  @include column(flex-start, $align, $reverse, $inline);\n}\n\n///\n/// @alias column-start()\n///\n@mixin col-start($align: center, $reverse: fals