n  $bottom: null,\n  $left: null,\n) {\n  @if $top {\n    top: $top;\n  }\n\n  @if $right {\n    right: $right;\n  }\n\n  @if $bottom {\n    bottom: $bottom;\n  }\n\n  @if $left {\n    left: $left;\n  }\n}\n\n@mixin inset(\n  $all: null,\n  $a: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $t: null,\n  $right: null,\n  $r: null,\n  $bottom: null,\n  $b: null,\n  $left: null,\n  $l: null,\n) {\n  @include -inset(\n    $top: if($top, $top, if($t, $t, if($y, $y, if($a, $a, $all)))),\n    $right: if($right, $right, if($r, $r, if($x, $x, if($a, $a, $all)))),\n    $bottom: if($bottom, $bottom, if($b, $b, if($y, $y, if($a, $a, $all)))),\n    $left: if($left, $left, if($l, $l, if($x, $x, if($a, $a, $all)))),\n  );\n}\n\n@mixin inset-all($all) {\n  @include inset($all: $all);\n}\n\n@mixin inset-none {\n  @include inset-all(0);\n}\n\n///\n/// @alias inset-none()\n///\n@mixin inset-0 {\n  @include inset-none;\n}\n\n@mixin inset-xy($x: null, $y: null) {\n  @include inset($x: $x, $y: $y);\n}\n\n@mixin inset-x($x) {\n  @include inset-xy($x: $x);\n}\n\n@mixin inset-x-none {\n  @include inset-x(0);\n}\n\n///\n/// @alias inset-x-none()\n///\n@mixin inset-x-0 {\n  @include inset-x-none;\n}\n\n@mixin inset-y($y) {\n  @include inset-xy($y: $y);\n}\n\n@mixin inset-y-none {\n  @include inset-y(0);\n}\n\n///\n/// @alias inset-y-none()\n///\n@mixin inset-y-0 {\n  @include inset-y-none;\n}\n\n@mixin top($top) {\n  @include inset($top: $top);\n}\n\n@mixin top-none {\n  @include top(0);\n}\n\n///\n/// @alias top-none()\n///\n@mixin top-0 {\n  @include top-none;\n}\n\n@mixin right($right) {\n  @include inset($right: $right);\n}\n\n@mixin right-none {\n  @include right(0);\n}\n\n///\n/// @alias right-none()\n///\n@mixin right-0 {\n  @include right-none;\n}\n\n@mixin bottom($bottom) {\n  @include inset($bottom: $bottom);\n}\n\n@mixin bottom-none {\n  @include bottom(0);\n}\n\n///\n/// @alias bottom-none()\n///\n@mixin bottom-0 {\n  @include bottom-none;\n}\n\n@mixin left($left) {\n  @include inset($left: $left);\n}\n\n@mixin left-none {\n  @include left(0);\n}\n\n///\n/// @alias left-none()\n///\n@mixin left-0 {\n  @include left-none;\n}\n\n@mixin unset-all {\n  @include inset-all(unset);\n}\n\n// translate\n\n@mixin translate(\n  $x: null,\n  $y: null,\n) {\n  @if meta.type-of($x) == 'number' or meta.type-of($y) == 'number' {\n    @if $x and $x != 0 and $y and $y != 0 {\n      transform: translate($x, $y);\n    } @else if $x and $x != 0 {\n      transform: translateX($x);\n    } @else if $y and $y != 0 {\n      transform: translateY($y);\n    }\n  }\n}\n\n///\n/// @access private\n///\n@mixin -position(\n  $position: relative,\n  $all: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @if not list.includes('relative' 'absolute' 'fixed' 'sticky', $position) {\n    @error 'Invalid $position value passed to the -position() mixin: #{$position}';\n  }\n\n  position: $position;\n  @include inset(\n    $all: $all,\n    $x: $x,\n    $y: $y,\n    $top: $top,\n    $right: $right,\n    $bottom: $bottom,\n    $left: $left,\n  );\n}\n\n// relative\n\n@mixin relative {\n  @include -position($position: relative);\n}\n\n///\n/// @alias relative()\n///\n@mixin rel {\n  @include relative;\n}\n\n// absolute\n\n@mixin absolute(\n  $all: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @include -position(\n    $position: absolute,\n    $all: $all,\n    $x: $x,\n    $y: $y,\n    $top: $top,\n    $right: $right,\n    $bottom: $bottom,\n    $left: $left,\n  );\n}\n\n///\n/// @alias absolute()\n///\n@mixin abs(\n  $a: null,\n  $x: null,\n  $y: null,\n  $t: null,\n  $r: null,\n  $b: null,\n  $l: null,\n) {\n  @include absolute(\n    $all: $a,\n    $x: $x,\n    $y: $y,\n    $top: $t,\n    $right: $r,\n    $bottom: $b,\n    $left: $l,\n  );\n}\n\n@mixin absolute-xy($x: null, $y: null) {\n  @include absolute($x: $x, $y: $y);\n}\n\n///\n/// @alias absolute-xy()\n///\n@mixin absolute-axis($horizontal: null, $vertical: null) {\n  @include absolute-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin absolute-all($margin) {\n  @include absolute($all: $margin);\n}\n\n///\n/// @alias absolute-all()\n///\n@mixin absolute-square($margin) {\n  @include absolute-all($margin);\n}\n\n@mixin absolute-fill {\n  @include absolute-all(0);\n}\n\n///\n/// @alias absolute-fill()\n///\n@mixin abs-fill {\n  @include absolute-fill;\n}\n\n@mixin absolute-0 {\n  @include absolute-fill;\n}\n\n///\n/// @alias absolute-0()\n///\n@mixin abs-0 {\n  @include absolute-0;\n}\n\n@mixin absolute-xy($x: null, $y: null) {\n  @include absolute($x: $x, $y: $y);\n}\n\n///\n/// @alias absolute-xy()\n///\n@mixin abs-xy($x: null, $y: null) {\n  @include absolute-xy($x: $x, $y: $y);\n}\n\n///\n/// @alias absolute-xy()\n///\n@mixin absolute-axis($vertical: null, $horizontal: null) {\n  @include absolute-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin absolute-x($x) {\n  @include absolute-xy($x: $x);\n}\n\n///\n/// @alias absolute-x()\n///\n@mixin abs-x($x) {\n  @include absolute-x($x);\n}\n\n@mixin absolute-y($y) {\n  @include absolute-xy($y: $y);\n}\n\n///\n/// @alias absolute-y()\n///\n@mixin abs-y($y) {\n  @include absolute-y($y);\n}\n\n@mixin absolute-anchor(\n  $x: null,\n  $y: null,\n  $x-prop: left,\n  $y-prop: top,\n) {\n  $translate-x: if($x, -$x, null);\n  $translate-y: if($y, -$y, null);\n\n  @if $translate-x and math.unit($translate-x) != '%' { // e.g., px\n    $translate-x: 0;\n  }\n\n  @if $translate-y and math.unit($translate-y) != '%' {\n    $translate-y: 0;\n  }\n\n  @include absolute(\n    $top: if($y-prop == top, $y, null),\n    $right: if($x-prop == right, $x, null),\n    $bottom: if($y-prop == bottom, $y, null),\n    $left: if($x-prop == left, $x, null),\n  );\n\n  @include translate($x: $translate-x, $y: $translate-y);\n}\n\n///\n/// @alias absolute-center()\n///\n@mixin abs-anchor(\n  $x: null,\n  $y: null,\n  $x-prop: left,\n  $y-prop: top,\n) {\n  @include absolute-anchor($x: $x, $y: $y, $x-prop: $x-prop, $y-prop: $y-prop);\n}\n\n@mixin absolute-center($x-prop: left, $y-prop: top) {\n  @include absolute-anchor($x: 50%, $y: 50%, $x-prop: $x-prop, $y-prop: $y-prop);\n}\n\n///\n/// @alias absolute-center()\n///\n@mixin abs-center($x-prop: left, $y-prop: top) {\n  @include absolute-center($x-prop: $x-prop, $y-prop: $y-prop);\n}\n\n// fixed\n\n@mixin fixed(\n  $all: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @include -position(\n    $position: fixed,\n    $all: $all,\n    $x: $x,\n    $y: $y,\n    $top: $top,\n    $right: $right,\n    $bottom: $bottom,\n    $left: $left,\n  );\n}\n\n@mixin fixed-xy($x: null, $y: null) {\n  @include fixed($x: $x, $y: $y);\n}\n\n///\n/// @alias fixed-xy()\n///\n@mixin fixed-axis($horizontal: null, $vertical: null) {\n  @include fixed-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin fixed-all($margin) {\n  @include fixed($all: $margin);\n}\n\n///\n/// @alias fixed-all()\n///\n@mixin fixed-square($margin) {\n  @include fixed-all($margin);\n}\n\n@mixin fixed-fill {\n  @include fixed-all(0);\n}\n\n///\n/// @alias fixed-fill()\n///\n@mixin fixed-0 {\n  @include fixed-fill;\n}\n\n@mixin fixed-x($x) {\n  @include fixed-xy($x: $x);\n}\n\n@mixin fixed-y($y) {\n  @include fixed-xy($y: $y);\n}\n\n@mixin fixed-anchor(\n  $x: null,\n  $y: null,\n  $x-prop: left,\n  $y-prop: top,\n) {\n  $translate-x: if($x, -$x, null);\n  $translate-y: if($y, -$y, null);\n\n  @if $translate-x and math.unit($translate-x) != '%' {\n    $translate-x: 0;\n  }\n\n  @if $translate-y and math.unit($translate-y) != '%' {\n    $translate-y: 0;\n  }\n\n  @include fixed(\n    $top: if($y-prop == top, $y, null),\n    $right: if($x-prop == right, $x, null),\n    $bottom: if($y-prop == bottom, $y, null),\n    $left: if($x-prop == left, $x, null),\n  );\n\n  @include translate($x: $translate-x, $y: $translate-y);\n}\n\n@mixin fixed-center($x-prop: left, $y-prop: top) {\n  @include fixed-anchor($x: 50%, $y: 50%, $x-prop: $x-prop, $y-prop: $y-prop);\n}\n\n// sticky\n\n@mixin sticky(\n  $all: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n  $t: null,\n  $r: null,\n  $b: null,\n  $l: null,\n) {\n  @include -position(\n    $position: sticky,\n    $all: $all,\n    $x: $x,\n    $y: $y,\n    $top: if($top, $top, $t),\n    $right: if($right, $right, $r),\n    $bottom: if($bottom, $bottom, $b),\n    $left: if($left, $left, $l),\n  );\n}\n\n@mixin sticky-all($all) {\n  @include sticky($all: $all);\n}\n\n@mixin sticky-fill {\n  @include sticky-all(0);\n}\n\n///\n/// @alias sticky-fill()\n///\n@mixin sticky-0 {\n  @include sticky-fill;\n}\n\n@mixin sticky-xy($x: null, $y: null) {\n  @include sticky($x: $x, $y: $y);\n}\n\n///\n/// @alias sticky-xy()\n///\n@mixin sticky-axis($vertical: null, $horizontal: null) {\n  @include sticky-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin sticky-x($x) {\n  @include sticky-xy($x: $x);\n}\n\n@mixin sticky-y($y) {\n  @include sticky-xy($y: $y);\n}\n","////\n/// @group spacing\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n////\n\n@use 'functions/list';\n\n@mixin -spacing(\n  $prop,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @if not list.includes('margin' 'padding', $prop) {\n    @error 'Invalid $prop value passed to the -spacing() mixin: #{$prop}';\n  }\n\n  @if $top and $right and $bottom and $left { // all directions specified\n    @if $right == $left {\n      @if $top == $bottom {\n        @if $top == $right { // $top (== $bottom) == $right (== $left)\n          #{$prop}: $top;\n        } @else { // $top (== $bottom) != $right (== $left)\n          #{$prop}: $top $right;\n        }\n      } @else { // $top != $bottom, but $right == $left\n        #{$prop}: $top $right $bottom;\n      }\n    } @else { // $right != $left\n      #{$prop}: $top $right $bottom $left;\n    }\n  } @else { // no