nt-size: 10px;\n  line-height: 11px;\n\n  .status {\n    @include spacing.margin($right: 4px);\n    @include font.apply(fonts.$mono);\n  }\n\n  .species {\n    font-weight: 600;\n\n    &.empty {\n      font-weight: 400;\n      opacity: 0.32;\n    }\n  }\n\n  .forme {\n    opacity: 0.8;\n  }\n\n  .level {\n    @include spacing.margin($left: 4px);\n    @include font.apply(fonts.$mono);\n    font-size: 8px;\n    text-transform: uppercase;\n    line-height: 9px;\n    opacity: 0.64;\n  }\n}\n\n.detailsRow.nickname {\n  @include font.apply(fonts.$primary);\n  font-size: 8px;\n  line-height: 9px;\n\n  .aka {\n    @include spacing.margin($right: 2px);\n    font-weight: 500;\n    letter-spacing: 0.01px;\n    text-indent: 0.01px;\n    text-transform: uppercase;\n    opacity: 0.4;\n  }\n\n  .value {\n    font-style: italic;\n    opacity: 0.72;\n  }\n}\n\n.types {\n  @include flex.row($align: center);\n\n  .type:not(:last-child) {\n    @include spacing.margin($right: 2px);\n  }\n}\n\n.teraType {\n  @include spacing.margin($left: 2px);\n}\n\n.stats {\n  display: grid;\n  grid-area: span 1 / 1;\n  grid-auto-columns: max-content;\n  grid-template-rows: max-content;\n  column-gap: 6px;\n  align-content: center;\n  @include spacing.margin($x: auto);\n}\n\n.stat {\n  @include flex.column-center;\n  grid-area: 1 / span 1;\n  text-align: center;\n\n  .statName {\n    // @include spacing.margin($bottom: 2px);\n    @include font.apply(fonts.$primary, ( font-weight: 600 ));\n    font-size: 8px;\n    text-transform: uppercase;\n    line-height: 9px;\n    opacity: 0.64;\n  }\n\n  .statValue {\n    @include font.apply(fonts.$mono);\n    font-size: 10px;\n    line-height: 11px;\n\n    // mimicing Showdown's Pokemon list selector thingy; BST values are faded like the header\n    &.bst {\n      opacity: 0.64;\n    }\n  }\n}\n\n.specs {\n  display: grid;\n  grid-area: span 1 / 1;\n  grid-template-columns: max-content minmax(0, 1fr);\n  grid-auto-rows: max-content;\n  column-gap: 8px;\n  row-gap: