nsition.apply(background-color, box-shadow);\n\n  .light & {\n    background-color: color.alpha(colors.$white, 0.8);\n    box-shadow: (\n      0 0 1px color.alpha(colors.$black, 0.16),\n      0 0 16px color.alpha(colors.$gray-dark, 0.16),\n    );\n  }\n\n  .light.mina & {\n    background-color: color.alpha(#FFF7FA, 0.8);\n    box-shadow: (\n      0 0 1px color.alpha(#770629, 0.32),\n      0 0 16px color.alpha(#9F1641, 0.16),\n    );\n  }\n\n  .dark & {\n    background-color: color.alpha(colors.$gray-darkest, 0.8);\n    box-shadow: (\n      0 0 1px color.alpha(colors.$white, 0.32),\n      0 0 8px color.alpha(colors.$gray-dark, 0.48),\n    );\n  }\n\n  .dark.mina & {\n    background-color: color.alpha(#100206, 0.48);\n  }\n\n  .glassy & {\n    backdrop-filter: blur(4px);\n  }\n\n  .glassy.light & {\n    background-color: color.alpha(colors.$white, 0.24);\n  }\n\n  .glassy.light.mina & {\n    background-color: color.alpha(#FFF7FA, 0.4);\n  }\n\n  .glassy.dark & {\n    background-color: color.alpha(colors.$black, 0.24);\n  }\n\n  .glassy.dark.mina & {\n    background-color: color.alpha(#100206, 0.24);\n  }\n}\n\n.settingsGroupTitle {\n  @include spacing.margin($bottom: 16px);\n  @include spacing.padding($x: 12px);\n  font-weight: 500;\n  font-size: 14px;\n  letter-spacing: 0.5px;\n  text-transform: uppercase;\n  @include transition.apply(color);\n  user-select: none;\n\n  .light & {\n    color: color.alpha(colors.$black, 0.84);\n  }\n\n  .dark & {\n    color: color.alpha(colors.$white, 0.84);\n  }\n}\n\n.settingsGroupFields {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr)); // note: 0 must come first before 1fr in minmax()\n  column-gap: 12px;\n  row-gap: 12px;\n  @include spacing.padding($x: 16px);\n\n  .inBattle & {\n    grid-template-columns: minmax(0, 1fr);\n    row-gap: 12px;\n  }\n\n  .settingsGroupTitle {\n    grid-area: span 1 / span 2;\n    @include spacing.margin($top: 16px, $bottom: 6px);\n    @include spacing.padding($x: 0);\n    font-size: 12px;\n\n    .inBattle & {\n      grid-area: span 1 / span 1;\n      @include spacing.margin($left: -0.5px); // matches letter-spacing of .settingsGroupTitle\n      text-align: center;\n    }\n\n    .light & {\n      color: color.alpha(colors.$black, 0.64);\n    }\n\n    .dark & {\n      color: color.alpha(colors.$white, 0.64);\n    }\n  }\n\n  .field {\n    grid-area: span 1 / span 1;\n    align-self: center;\n  }\n\n  // fixes tooltips appearing in empty spaces, which could get annoying\n  // (otherwise, it'll extend like `width: 100%` !!)\n  .switchField {\n    width: fit-content;\n  }\n\n  .singleColumn {\n    grid-area: span 1 / span 2;\n  }\n}\n\n// this is basically a container for a pseudo-component frankensteined\n// from other components (namely the NHKO fields)\n// (should typically be applied with .field)\n.customField {\n  @include spacing.padding($x: 5px, $y: 2px);\n}\n\n// mimics the labels of form components\n.customFieldLabel {\n  font-weight: 500;\n  font-size: 12px;\n  user-select: none;\n\n  .inBattle & {\n    text-align: center;\n  }\n\n  &.top {\n    @include spacing.margin($bottom: 3px);\n  }\n\n  &.right {\n    @include spacing.margin($left: 10px);\n  }\n\n  &.bottom {\n    @include spacing.margin($top: 3px);\n  }\n\n  &.left {\n    @include spacing.margin($right: 10px);\n  }\n}\n\n.customFieldRow {\n  @include flex.row($align: center);\n  @include spacing.margin($top: 7px);\n\n  &.centered {\n    justify-content: center;\n  }\n\n  .customFieldInput:not(:last-child) {\n    @include spacing.margin($right: 5px);\n  }\n}\n\n.textField {\n  @include spacing.padding($x: 3px, $y: 5px);\n  font-size: 10px;\n\n  &.nhkoLabelField {\n    max-width: 75px;\n  }\n\n  &.nhkoColorField {\n    max-width: 70px;\n  }\n\n  .textFieldInput {\n    text-align: center;\n  }\n}\n\n.tooltipContent {\n  max-width: 248px;\n  font-size: 10px;\n  text-align: center;\n  line-height: 12px;\n  white-space: normal;\n  user-select: none;\n}\n\n// these are primarily used for the defaultAutoPreset Field in AutoFeaturesSettingsPane\n.strongText {\n  font-weight: 600;\n}\n\n.blueColor {\n  color: colors.$blue;\n}\n","////\n/// @group position\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n////\n\n@use 'sass:math';\n@use 'sass:meta';\n@use 'functions/list';\n\n///\n/// @access private\n///\n@mixin -inset(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @if $top {\n    top: $top;\n  }\n\n  @if $right {\n    right: $right;\n  }\n\n  @if $bottom {\n    bottom: $bottom;\n  }\n\n  @if $left {\n    left: $left;\n  }\n}\n\n@mixin inset(\n  $all: null,\n  $a: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $t: null,\n  $right: null,\n  $r: null,\n  $bottom: null,\n  $b: null,\n  $left: null,\n  $l: null,\n) {\n  @include -inset(\n    $top: if($top, $top, if($t, $t, if($y, $y, if($a, $a, $all)))),\n    $right: if($right, $right, if($r, $r, if($x, $x, if($a, $a, $all)))),\n    $bottom: if($bottom, $bottom, if($b, $b, if($y, $y, if($a, $a, $all)))),\n    $left: if($left, $left, if($l, $l, if($x, $x, if($a, $a, $all)))),\n  );\n}\n\n@mixin inset-all($all) {\n  @include inset($all: $all);\n}\n\n@mixin inset-none {\n  @include inset-all(0);\n}\n\n///\n/// @alias inset-none()\n///\n@mixin inset-0 {\n  @include inset-none;\n}\n\n@mixin inset-xy($x: null, $y: null) {\n  @include inset($x: $x, $y: $y);\n}\n\n@mixin inset-x($x) {\n  @include inset-xy($x: $x);\n}\n\n@mixin inset-x-none {\n  @include inset-x(0);\n}\n\n///\n/// @alias inset-x-none()\n///\n@mixin inset-x-0 {\n  @include inset-x-none;\n}\n\n@mixin inset-y($y) {\n  @include inset-xy($y: $y);\n}\n\n@mixin inset-y-none {\n  @include inset-y(0);\n}\n\n///\n/// @alias inset-y-none()\n///\n@mixin inset-y-0 {\n  @include inset-y-none;\n}\n\n@mixin top($top) {\n  @include inset($top: $top);\n}\n\n@mixin top-none {\n  @include top(0);\n}\n\n///\n/// @alias top-none()\n///\n@mixin top-0 {\n  @include top-none;\n}\n\n@mixin right($right) {\n  @include inset($right: $right);\n}\n\n@mixin right-none {\n  @include right(0);\n}\n\n///\n/// @alias right-none()\n///\n@mixin right-0 {\n  @include right-none;\n}\n\n@mixin bottom($bottom) {\n  @include inset($bottom: $bottom);\n}\n\n@mixin bottom-none {\n  @include bottom(0);\n}\n\n///\n/// @alias bottom-none()\n///\n@mixin bottom-0 {\n  @include bottom-none;\n}\n\n@mixin left($left) {\n  @include inset($left: $left);\n}\n\n@mixin left-none {\n  @include left(0);\n}\n\n///\n/// @alias left-none()\n///\n@mixin left-0 {\n  @include left-none;\n}\n\n@mixin unset-all {\n  @include inset-all(unset);\n}\n\n// translate\n\n@mixin translate(\n  $x: null,\n  $y: null,\n) {\n  @if meta.type-of($x) == 'number' or meta.type-of($y) == 'number' {\n    @if $x and $x != 0 and $y and $y != 0 {\n      transform: translate($x, $y);\n    } @else if $x and $x != 0 {\n      transform: translateX($x);\n    } @else if $y and $y != 0 {\n      transform: translateY($y);\n    }\n  }\n}\n\n///\n/// @access private\n///\n@mixin -position(\n  $position: relative,\n  $all: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @if not list.includes('relative' 'absolute' 'fixed' 'sticky', $position) {\n    @error 'Invalid $position value passed to the -position() mixin: #{$position}';\n  }\n\n  position: $position;\n  @include inset(\n    $all: $all,\n    $x: $x,\n    $y: $y,\n    $top: $top,\n    $right: $right,\n    $bottom: $bottom,\n    $left: $left,\n  );\n}\n\n// relative\n\n@mixin relative {\n  @include -position($position: relative);\n}\n\n///\n/// @alias relative()\n///\n@mixin rel {\n  @include relative;\n}\n\n// absolute\n\n@mixin absolute(\n  $all: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @include -position(\n    $position: absolute,\n    $all: $all,\n    $x: $x,\n    $y: $y,\n    $top: $top,\n    $right: $right,\n    $bottom: $bottom,\n    $left: $left,\n  );\n}\n\n///\n/// @alias absolute()\n///\n@mixin abs(\n  $a: null,\n  $x: null,\n  $y: null,\n  $t: null,\n  $r: null,\n  $b: null,\n  $l: null,\n) {\n  @include absolute(\n    $all: $a,\n    $x: $x,\n    $y: $y,\n    $top: $t,\n    $right: $r,\n    $bottom: $b,\n    $left: $l,\n  );\n}\n\n@mixin absolute-xy($x: null, $y: null) {\n  @include absolute($x: $x, $y: $y);\n}\n\n///\n/// @alias absolute-xy()\n///\n@mixin absolute-axis($horizontal: null, $vertical: null) {\n  @include absolute-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin absolute-all($margin) {\n  @include absolute($all: $margin);\n}\n\n///\n/// @alias absolute-all()\n///\n@mixin absolute-square($margin) {\n  @include absolute-all($margin);\n}\n\n@mixin absolute-fill {\n  @include absolute-all(0);\n}\n\n///\n/// @alias absolute-fill()\n///\n@mixin abs-fill {\n  @include absolute-fill;\n}\n\n@mixin absolute-0 {\n  @include absolute-fill;\n}\n\n///\n/// @alias absolute-0()\n///\n@mixin abs-0 {\n  @include absolute-0;\n}\n\n@mixin absolute-xy($x: null, $y: null) {\n  @include absolute($x: $x, $y: $y);\n}\n\n///\n/// @alias absolute-xy()\n///\n@mixin abs-xy($x: null, $y: null) {\n  @include absolute-xy($x: $x, $y: $y);\n}\n\n///\n/// @alias absolute-xy()\n///\n@mixin absolute-axis($vertical: null, $horizontal: null) {\n  @include absolute-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin absolute-x($x) {\n  @include absolute-xy($x: $x);\n}\n\n///\n/// @alias absolute-x()\n///\n@mixin abs-x($x) {\n  @include absolute-x($x);\n}\n\n@mixin absolute-y($y) {\n  @include absolute-xy($y: $y);\n}\n\n///\n/// @alias absolute-y()\n///\n@mixin abs-y($y) {\n  @include absolute-y($y);\n}\n\n@mixin absolute-anchor(\n  $x: null,\n  $y: null,\n  $x-prop: left,\n  $y-prop: top,\n) {\n  $translate-x: if($x, -$x, null);\n  $translate-y: if($y, -$y, null);\n\n  @if $translate-x and math.unit($translate-x) != '%' { // e.g., px\n    $translate-x: 0;\n  }\n\n  @if $translate-y and math.unit($translate-y) != '%' {\n    $translate-y: 0;\n  }\n\n  @include absolute(\n    $top: if($y-prop == top, $y, null),\n    $right: if($x-prop == right, $x, null),\n    $bottom: if($y-prop == bottom, $y, null),\n    $left: if($x-prop == left, $x, null),\n  );\n\n  @include translate($x: $translate-x, $y: $translate-y);\n}\n\n///\n/// @alias absolute-center()\n///\n@mixin abs-anchor(\n  $x: null,\n  $y: null,\n  $x-prop: left,\n  $y-prop: top,\n) {\n  @include absolute-anchor($x: $x, $y: $y, $x-prop: $x-prop, $y-prop: $y-prop);\n}\n\n@mixin absolute-center($x-prop: left, $y-prop: top) {\n  @include absolute-anchor($x: 50%, $y: 50%, $x-prop: $x-prop, $y-prop: $y-prop);\n}\n\n///\n/// @alias absolute-center()\n///\n@mixin abs-center($x-prop: left, $y-prop: top) {\n  @include absolute-center($x-prop: $x-prop, $y-prop: $y-prop);\n}\n\n// fixed\n\n@mixin fixed(\n  $all: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @include -position(\n    $position: fixed,\n    $all: $all,\n    $x: $x,\n    $y: $y,\n    $top: $top,\n    $right: $right,\n    $bottom: $bottom,\n    $left: $left,\n  );\n}\n\n@mixin fixed-xy($x: null, $y: null) {\n  @include fixed($x: $x, $y: $y);\n}\n\n///\n/// @alias fixed-xy()\n///\n@mixin fixed-axis($horizontal: null, $vertical: null) {\n  @include fixed-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin fixed-all($margin) {\n  @include fixed($all: $margin);\n}\n\n///\n/// @alias fixed-all()\n///\n@mixin fixed-square($margin) {\n  @include fixed-all($margin);\n}\n\n@mixin fixed-fill {\n  @include fixed-all(0);\n}\n\n///\n/// @alias fixed-fill()\n///\n@mixin fixed-0 {\n  @include fixed-fill;\n}\n\n@mixin fixed-x($x) {\n  @include fixed-xy($x: $x);\n}\n\n@mixin fixed-y($y) {\n  @include fixed-xy($y: $y);\n}\n\n@mixin fixed-anchor(\n  $x: null,\n  $y: null,\n  $x-prop: left,\n  $y-prop: top,\n) {\n  $translate-x: if($x, -$x, null);\n  $translate-y: if($y, -$y, null);\n\n  @if $translate-x and math.unit($translate-x) != '%' {\n    $translate-x: 0;\n  }\n\n  @if $translate-y and math.unit($translate-y) != '%' {\n    $translate-y: 0;\n  }\n\n  @include fixed(\n    $top: if($y-prop == top, $y, null),\n    $right: if($x-prop == right, $x, null),\n    $bottom: if($y-prop == bottom, $y, null),\n    $left: if($x-prop == left, $x, null),\n  );\n\n  @include translate($x: $translate-x, $y: $translate-y);\n}\n\n@mixin fixed-center($x-prop: left, $y-prop: top) {\n  @include fixed-anchor($x: 50%, $y: 50%, $x-prop: $x-prop, $y-prop: $y-prop);\n}\n\n// sticky\n\n@mixin sticky(\n  $all: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n  $t: null,\n  $r: null,\n  $b: null,\n  $l: null,\n) {\n  @include -position(\n    $position: sticky,\n    $all: $all,\n    $x: $x,\n    $y: $y,\n    $top: if($top, $top, $t),\n    $right: if($right, $right, $r),\n    $bottom: if($bottom, $bottom, $b),\n    $left: if($left, $left, $l),\n  );\n}\n\n@mixin sticky-all($all) {\n  @include sticky($all: $all);\n}\n\n@mixin sticky-fill {\n  @include sticky-all(0);\n}\n\n///\n/// @alias sticky-fill()\n///\n@mixin sticky-0 {\n  @include sticky-fill;\n}\n\n@mixin sticky-xy($x: null, $y: null) {\n  @include sticky($x: $x, $y: $y);\n}\n\n///\n/// @alias sticky-xy()\n///\n@mixin sticky-axis($vertical: null, $horizontal: null) {\n  @include sticky-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin sticky-x($x) {\n  @include sticky-xy($x: $x);\n}\n\n@mixin sticky-y($y) {\n  @include sticky-xy($y: $y);\n}\n","////\n/// @group transition\n/// @author Keith Choison\n////\n\n@use 'sass:list';\n@use 'sass:meta';\n@use 'config/animations';\n\n@mixin apply($props...) {\n  $transitions: ();\n\n  @for $i from 1 through list.length($props) {\n    $prop: list.nth($props, $i);\n\n    $name: $prop;\n    $duration: animations.$transition-duration;\n    $function: animations.$transition-function;\n\n    @if meta.type-of($prop) == 'list' and list.length($prop) > 1 {\n      $name: list.nth($prop, 1);\n\n      @if list.nth($prop, 2) {\n        $duration: list.nth($prop, 2);\n      }\n\n      @if list.length($prop) > 2 and list.nth($prop, 3) {\n        $function: list.nth($prop, 3);\n      }\n    }\n\n    $transitions: list.append($transitions, '#{$name} #{$duration} #{$function}');\n  }\n\n  @if list.length($transitions) > 0 {\n    transition: #{list.zip($transitions)};\n  }\n}\n","$black: #000000;\n$white: #FFFFFF;\n\n$gray-lighter: #EEEEEE; // MD Gray 200\n$gray-light: #BDBDBD; // MD Gray 400\n$gray: #9E9E9E; // MD Gray 500\n$gray-dark: #424242; // MD Gray 800\n$gray-darker: #212121; // MD Gray 900\n$gray-darkest: #121212;\n\n$red: #F44336; // MD Red 500\n$green: #4CAF50; // MD Green 500\n$blue: #2196F3; // MD Blue 500\n\n$pink: #E91E63; // MD Pink 500\n$orange: #FF9800; // MD Orange 500\n$cyan: #00ACC1; // MD Cyan 500\n\n$transparent-black: rgba(0, 0, 0, 0);\n$transparent-white: rgba(255, 255, 255, 0);\n$transparent: $transparent-white;\n\n$showdown-background-light: #EEF2F5;\n$showdown-background-dark: #444444;\n","////\n/// @group font\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n////\n\n@use 'sass:meta';\n@use 'sass:map';\n@use 'config/fonts';\n\n@mixin apply($font, $overrides: null) {\n  $props: (\n    'font-family',\n    'font-stretch',\n    'font-weight',\n  );\n\n  @each $prop in $props {\n    $value: map.get($font, $prop);\n\n    @if meta.type-of($overrides) == map and map.has-key($overrides, $prop) {\n      $value: map.get($overrides, $prop);\n    }\n\n    @if $value {\n      #{$prop}: $value;\n    } @else {\n      @warn 'Font prop `#{$prop}` was ignored because no value was set.';\n    }\n  }\n}\n\n///\n/// Applies the primary font.\n///\n@mixin primary($weight: 400) {\n  @include apply(fonts.$primary, ( font-weight: $weight ));\n}\n\n///\n/// Applies the monospaced font.\n///\n@mixin monospace($weight: 400) {\n  @include apply(fonts.$mono, ( font-weight: $weight ));\n}\n\n///\n/// @alias monospace()\n///\n@mixin mono($weight: 400) {\n  @includ