on.toggleButton {\n  @include spacing.margin($left: 4px);\n  font-size: 8px;\n\n  &.lessSpacing {\n    @include spacing.margin($left: 2px);\n  }\n}\n\nbutton.editButton {\n  @include spacing.margin($left: 2px);\n}\n\n.teraButtonLabel {\n  $gradient: linear-gradient(\n    // to right,\n    60deg,\n\n    color.alpha(colors.$black, 0.76) 25%,\n\n    // #55C0EC,\n    color.shade(#63B44A, 32%) 25%,\n    // #E96B7D,\n    color.shade(#43B9DC, 24%) 49%,\n\n    // #7ECADA,\n    // #DBE6A7,\n    #ACD7BF 49%,\n    color.shade(#6DC5E5, 10%) 75%,\n\n    color.alpha(colors.$white, 0.76) 75%,\n  );\n\n  // position: relative;\n  // color: colors.$transparent;\n  // background-image: $gradient;\n  // background-size: 400% 100%;\n  // background-position: 0% 0%;\n  // background-clip: text;\n  // mix-blend-mode: multiply;\n  @include transition.apply((color, 150ms), background-position);\n\n  &.available {\n    color: colors.$transparent;\n    background-image: $gradient;\n    background-size: 420% 100%;\n    background-position: 0% 0%;\n    background-clip: text;\n  }\n\n  .light & {\n    background-position: 0% 0%;\n\n    &.available {\n      background-position: 165% 0%;\n    }\n  }\n\n  .dark & {\n    background-position: 365% 0%;\n\n    &.available {\n      background-position: 331% 0%;\n    }\n  }\n}\n\nbutton.ultButton {\n  min-width: 26px;\n}\n\n.quickEditor {\n  @include flex.row-center;\n\n  .moveProperty {\n    @include spacing.margin($right: 6px);\n    font-size: 8px;\n    user-select: none;\n  }\n\n  .valueField {\n    max-width: 16px;\n\n    &::before {\n      @include position.absolute($x: -3px, $y: 0);\n    }\n  }\n\n  .propertyName {\n    opacity: 0.4;\n\n    i:global(.fa-close) {\n      font-size: 8px;\n      line-height: 9px;\n    }\n  }\n}\n\nbutton.damageButton {\n  .light &:not(:hover):not(.active) .damageButtonLabel.noDamage {\n    color: color.alpha(colors.$black, 0.48);\n  }\n\n  .dark &:not(:hover):not(.active) .damageButtonLabel.noDamage {\n    color: color.alpha(colors.$white, 0.48);\n  }\n\n  // by default, a disabled button will have 0.3 opacity\n  &.disabled {\n    opacity: 1;\n  }\n}\n\n.damageButtonLabel {\n  .light & {\n    color: colors.$black;\n  }\n\n  .dark & {\n    color: colors.$white;\n  }\n\n  &.noCopy.noDamage {\n    .light & {\n      color: color.alpha(colors.$black, 0.48);\n    }\n\n    .dark & {\n      color: color.alpha(colors.$white, 0.48);\n    }\n  }\n}\n\n.copiedBadge {\n  @include position.absolute($top: -3px, $left: 50%);\n  white-space: nowrap;\n}\n\n.descTooltip {\n  position: relative;\n  max-width: 200px;\n  text-align: center;\n  white-space: normal;\n  user-select: none;\n\n  .ultUsage {\n    font-size: 8px;\n    text-transform: uppercase;\n    @include transition.apply(color, opacity);\n\n    &.available {\n      color: colors.$blue;\n    }\n\n    &.consumed {\n      opacity: 0.8;\n    }\n  }\n}\n\n.boldDesc {\n  font-weight: 600;\n}\n\n.editorItem {\n  grid-area: span 1 / span 2;\n  @include flex.row-between;\n  align-self: center;\n\n  &.editorHeader {\n    @include flex.row-between;\n    @include spacing.margin($bottom: 0);\n  }\n\n  .moveProperty {\n    font-size: 8px;\n    user-select: none;\n  }\n\n  .valueField {\n    max-width: 22px;\n    @include spacing.margin($right: 6px);\n\n    .autoValueInput::placeholder {\n      font-size: 8px;\n    }\n\n    &::before {\n      @include position.absolute($x: -3px, $y: 0); // remove \"padding\" from absoluteHover\n    }\n  }\n}\n\n.editorLeft {\n  @include flex.row($align: center);\n  flex-wrap: wrap;\n\n  & > *:not(:last-child) {\n    @include spacing.margin($right: 6px);\n  }\n}\n\n.editorRight {\n  text-align: right;\n}\n\nbutton.editorButton {\n  font-size: 8px;\n  // line-height: 9px;\n  @include transition.apply(color, background-color, box-shadow, opacity);\n\n  &.readOnly {\n    user-select: none;\n    pointer-events: none;\n  }\n}\n\n.statVsLabel {\n  @include spacing.margin($x: 3px);\n  @include font.apply(fonts.$mono, ( font-weight: 600 ));\n  font-size: 6px;\n  letter-spacing: 0.25px;\n  opacity: 0.64;\n}\n","////\n/// @group spacing\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n////\n\n@use 'functions/list';\n\n@mixin -spacing(\n  $prop,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @if not list.includes('margin' 'padding', $prop) {\n    @error 'Invalid $prop value passed to the -spacing() mixin: #{$prop}';\n  }\n\n  @if $top and $right and $bottom and $left { // all directions specified\n    @if $right == $left {\n      @if $top == $bottom {\n        @if $top == $right { // $top (== $bottom) == $right (== $left)\n          #{$prop}: $top;\n        } @else { // $top (== $bottom) != $right (== $left)\n          #{$prop}: $top $right;\n        }\n      } @else { // $top != $bottom, but $right == $left\n        #{$prop}: $top $right $bottom;\n      }\n    } @else { // $right != $left\n      #{$prop}: $top $right $bottom $left;\n    }\n  } @else { // not all directions specified\n    @if $top {\n      #{$prop}-top: $top;\n    }\n\n    @if $right {\n      #{$prop}-right: $right;\n    }\n\n    @if $bottom {\n      #{$prop}-bottom: $bottom;\n    }\n\n    @if $left {\n      #{$prop}-left: $left;\n    }\n  }\n}\n\n// margin\n\n@mixin margin(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n  $x: null,\n  $y: null,\n  $all: null,\n) {\n  @include -spacing(\n    $prop: margin,\n    $top: if($top, $top, if($y, $y, $all)),\n    $right: if($right, $right, if($x, $x, $all)),\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\n    $left: if($left, $left, if($x, $x, $all)),\n  );\n}\n\n///\n/// @alias margin()\n///\n@mixin m(\n  $a: null,\n  $x: null,\n  $y: null,\n  $t: null,\n  $r: null,\n  $b: null,\n  $l: null,\n) {\n  @include margin(\n    $all: $a,\n    $x: $x,\n    $y: $y,\n    $top: $t,\n    $right: $r,\n    $bottom: $b,\n    $left: $l,\n  );\n}\n\n@mixin margin-xy($x: null, $y: null) {\n  @include margin($x: $x, $y: $y);\n}\n\n///\n/// @alias margin-axis()\n///\n@mixin margin-axis($horizontal: null, $vertical: null) {\n  @include margin-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin margin-center {\n  @include margin($x: auto);\n}\n\n///\n/// @alias margin-center()\n///\n@mixin mx-auto {\n  @include margin-center;\n}\n\n@mixin margin-middle {\n  @include margin($y: auto);\n}\n\n///\n/// @alias margin-middle()\n///\n@mixin my-auto {\n  @include margin-middle;\n}\n\n@mixin margin-all($margin) {\n  @include margin($all: $margin);\n}\n\n///\n/// @alias margin-all()\n///\n@mixin margin-square($margin) {\n  @include margin-all($margin);\n}\n\n@mixin margin-auto {\n  @include margin-all(auto);\n}\n\n///\n/// @alias margin-auto()\n///\n@mixin m-auto {\n  @include margin-auto;\n}\n\n@mixin margin-none {\n  @include margin-all(0);\n}\n\n///\n/// @alias margin-none()\n///\n@mixin m-none {\n  @include margin-none;\n}\n\n///\n/// @alias m-none()\n///\n@mixin m-0 {\n  @include m-none;\n}\n\n@mixin margin-xy($x: null, $y: null) {\n  @include margin($x: $x, $y: $y);\n}\n\n///\n/// @alias margin-xy()\n///\n@mixin margin-axis($vertical: null, $horizontal: null) {\n  @include margin-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin margin-x($x: null) {\n  @include margin($x: $x);\n}\n\n///\n/// @alias margin-x()\n///\n@mixin mx($x: null) {\n  @include margin-x($x: $x);\n}\n\n@mixin mx-none {\n  @include mx($x: 0);\n}\n\n///\n/// @alias mx-none()\n///\n@mixin mx-0 {\n  @include mx-none;\n}\n\n@mixin margin-y($y: null) {\n  @include margin($y: $y);\n}\n\n///\n/// @alias margin-y()\n///\n@mixin my($y: null) {\n  @include margin-y($y: $y);\n}\n\n@mixin my-none {\n  @include my($y: 0);\n}\n\n///\n/// @alias my-none()\n///\n@mixin my-0 {\n  @include my-none;\n}\n\n@mixin margin-top($top: null) {\n  @include margin($top: $top);\n}\n\n///\n/// @alias margin-top()\n///\n@mixin mt($top: null) {\n  @include margin-top($top);\n}\n\n@mixin mt-none {\n  @include mt(0);\n}\n\n///\n/// @alias mt-none()\n///\n@mixin mt-0 {\n  @include mt-none;\n}\n\n@mixin margin-right($right: null) {\n  @include margin($right: $right);\n}\n\n///\n/// @alias margin-right()\n///\n@mixin mr($right: null) {\n  @include margin-right($right);\n}\n\n@mixin mr-none {\n  @include mr($right: 0);\n}\n\n///\n/// @alias mr-none()\n///\n@mixin mr-0 {\n  @include mr-none;\n}\n\n@mixin margin-bottom($bottom: null) {\n  @include margin($bottom: $bottom);\n}\n\n///\n/// @alias margin-bottom()\n///\n@mixin mb($bottom: null) {\n  @include margin-bottom($bottom: $bottom);\n}\n\n@mixin mb-none {\n  @include mb($bottom: 0);\n}\n\n///\n/// @alias mb-none()\n///\n@mixin mb-0 {\n  @include mb-none;\n}\n\n@mixin margin-left($left: null) {\n  @include margin($left: $left);\n}\n\n///\n/// @alias margin-left()\n///\n@mixin ml($left: null) {\n  @include margin-left($left: $left);\n}\n\n@mixin ml-none {\n  @include ml($left: 0);\n}\n\n///\n/// @alias ml-none()\n///\n@mixin ml-0 {\n  @include ml-none;\n}\n\n// padding\n\n@mixin padding(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n  $x: null,\n  $y: null,\n  $all: null,\n) {\n  @include -spacing(\n    $prop: padding,\n    $top: if($top, $top, if($y, $y, $all)),\n    $right: if($right, $right, if($x, $x, $all)),\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\n    $left: if($left, $left, if($x, $x, $all)),\n  );\n}\n\n///\n/// @alias padding()\n///\n@mixin p(\n  $a: null,\n  $x: null,\n  $y: null,\n  $t: null,\n  $r: null,\n  $b: null,\n  $l: null,\n) {\n  @include padding(\n    $all: $a,\n    $x: $x,\n    $y: $y,\n    $top: $t,\n    $right: $r,\n    $bottom: $b,\n    $left: $l,\n  );\n}\n\n@mixin padding-xy($x: null, $y: null) {\n  @include padding($x: $x, $y: $y);\n}\n\n///\n/// @alias padding-xy()\n///\n@mixin padding-axis($horizontal: null, $vertical: null) {\n  @include padding-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin padding-all($padding) {\n  @include padding($all: $padding);\n}\n\n///\n/// @alias padding-all()\n///\n@mixin padding-square($padding) {\n  @include padding-all($padding);\n}\n\n@mixin padding-none {\n  @include padding-all(0);\n}\n\n///\n/// @alias padding-none()\n///\n@mixin p-none {\n  @include padding-none;\n}\n\n///\n/// @alias p-none()\n///\n@mixin p-0 {\n  @include p-none;\n}\n\n@mixin padding-x($x: null) {\n  @include padding($x: $x);\n}\n\n///\n/// @alias padding-x()\n///\n@mixin px($x: null) {\n  @include padding-x($x);\n}\n\n@mixin px-none {\n  @include px(0);\n}\n\n///\n/// @alias px-none()\n///\n@mixin px-0 {\n  @include px-none;\n}\n\n@mixin padding-y($y: null) {\n  @include padding($y: $y);\n}\n\n///\n/// @alias padding-y()\n///\n@mixin py($y: null) {\n  @include padding-y($y);\n}\n\n@mixin py-none {\n  @include py(0);\n}\n\n///\n/// @alias py-none()\n///\n@mixin py-0 {\n  @include py-none;\n}\n\n@mixin padding-top($top: null) {\n  @include padding($top: $top);\n}\n\n///\n/// @alias padding-top()\n///\n@mixin pt($top: null) {\n  @include padding-top($top);\n}\n\n@mixin pt-none {\n  @include pt(0);\n}\n\n///\n/// @alias padding-top()\n///\n@mixin pt-0 {\n  @include pt-none;\n}\n\n@mixin padding-right($right: null) {\n  @include padding($right: $right);\n}\n\n///\n/// @alias padding-right()\n///\n@mixin pr($right: null) {\n  @include padding-right($right);\n}\n\n@mixin pr-none {\n  @include pr(0);\n}\n\n///\n/// @alias pr-none()\n///\n@mixin pr-0 {\n  @include pr-none;\n}\n\n@mixin padding-bottom($bottom: null) {\n  @include padding($bottom: $bottom);\n}\n\n///\n/// @alias padding-bottom()\n///\n@mixin pb($bottom: null) {\n  @include padding-bottom($bottom);\n}\n\n@mixin pb-none {\n  @include pb(0);\n}\n\n///\n/// @alias pb-none()\n///\n@mixin pb-0 {\n  @include pb-none;\n}\n\n@mixin padding-left($left: null) {\n  @include padding($left: $left);\n}\n\n///\n/// @alias padding-left()\n///\n@mixin pl($left: null) {\n  @include padding-left($left);\n}\n\n@mixin pl-none {\n  @include pl(0);\n}\n\n///\n/// @alias pl-none()\n///\n@mixin pl-0 {\n  @include pl-none;\n}\n","////\n/// @group transition\n/// @author Keith Choison\n////\n\n@use 'sass:list';\n@use 'sass:meta';\n@use 'config/animations';\n\n@mixin apply($props...) {\n  $transitions: ();\n\n  @for $i from 1 through list.length($props) {\n    $prop: list.nth($props, $i);\n\n    $name: $prop;\n    $duration: animations.$transition-duration;\n    $function: animations.$transition-function;\n\n    @if meta.type-of($prop) == 'list' and list.length($prop) > 1 {\n      $name: list.nth($prop, 1);\n\n      @if list.nth($prop, 2) {\n        $duration: list.nth($prop, 2);\n      }\n\n      @if list.length($prop) > 2 and list.nth($prop, 3) {\n        $function: list.nth($prop, 3);\n      }\n    }\n\n    $transitions: list.append($transitions, '#{$name} #{$duration} #{$function}');\n  }\n\n  @if list.length($transitions) > 0 {\n    transition: #{list.zip($transitions)};\n  }\n}\n","////\n/// @group font\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n////\n\n@use 'sass:meta';\n@use 'sass:map';\n@use 'config/fonts';\n\n@mixin apply($font, $overrides: null) {\n  $props: (\n    'font-family',\n    'font-stretch',\n    'font-weight',\n  );\n\n  @each $prop in $props {\n    $value: map.get($font, $prop);\n\n    @if meta.type-of($overrides) == map and map.has-key($overrides, $prop) {\n      $value: map.get($overrides, $prop);\n    }\n\n    @if $value {\n      #{$prop}: $value;\n    } @else {\n      @warn 'Font prop `#{$prop}` was ignored because no value was set.';\n    }\n  }\n}\n\n///\n/// Applies the primary font.\n///\n@mixin primary($weight: 400) {\n  @include apply(fonts.$primary, ( font-weight: $weight ));\n}\n\n///\n/// Applies the monospaced font.\n///\n@mixin monospace($weight: 400) {\n  @include apply(fonts.$mono, ( font-weight: $weight ));\n}\n\n///\n/// @alias monospace()\n///\n@mixin mono($weight: 400) {\n  @include monospace($weight);\n}\n","///\n/// @group flex\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n///\n\n///\n/// @access private\n///\n@mixin -flex(\n  $direction: null,\n  $justify: null,\n  $align: null,\n  $inline: false,\n) {\n  display: if($inline, inline-flex, flex);\n\n  @if $direction and $direction != row {\n    flex-direction: $direction;\n  }\n\n  @if $justify and $justify != flex-start {\n    justify-content: $justify;\n  }\n\n  @if $align and $align != stretch {\n    align-items: $align;\n  }\n}\n\n// rows\n\n@mixin row(\n  $justify: null,\n  $align: null,\n  $reverse: false,\n  $inline: false,\n) {\n  @include -flex(\n    if($reverse, row-reverse, row),\n    $justify,\n    $align,\n    $inline,\n  );\n}\n\n@mixin row-stretch($reverse: false, $inline: false) {\n  @include row(stretch, stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-stretch()\n///\n@mixin stretch($reverse: false, $inline: false) {\n  @include row-stretch($reverse, $inline);\n}\n\n@mixin row-start($align: center, $reverse: false, $inline: false) {\n  @include row(flex-start, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-start()\n///\n@mixin start($align: center, $reverse: false, $inline: false) {\n  @include row-start($align, $reverse, $inline);\n}\n\n@mixin row-start-stretch($reverse: false, $inline: false) {\n  @include row-start(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-start-stretch()\n///\n@mixin start-stretch($reverse: false, $inline: false) {\n  @include row-start-stretch($reverse, $inline);\n}\n\n@mixin row-center($align: center, $reverse: false, $inline: false) {\n  @include row(center, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-center()\n///\n@mixin center($align: center, $reverse: false, $inline: false) {\n  @include row-center($align, $reverse, $inline);\n}\n\n@mixin row-center-stretch($reverse: false, $inline: false) {\n  @include row-center(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-center-stretch()\n///\n@mixin center-stretch($reverse: false, $inline: false) {\n  @include row-center-stretch($reverse, $inline);\n}\n\n@mixin row-end($align: center, $reverse: false, $inline: false) {\n  @include row(flex-end, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-end()\n///\n@mixin end($align: center, $reverse: false, $inline: false) {\n  @include row-end($align, $reverse, $inline);\n}\n\n@mixin row-end-stretch($reverse: false, $inline: false) {\n  @include row-end(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-end-stretch()\n///\n@mixin end-stretch($reverse: false, $inline: false) {\n  @include row-end-stretch($reverse, $inline);\n}\n\n@mixin row-between($align: center, $reverse: false, $inline: false) {\n  @include row(space-between, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-between()\n///\n@mixin between($align: center, $reverse: false, $inline: false) {\n  @include row-between($align, $reverse, $inline);\n}\n\n@mixin row-between-stretch($reverse: false, $inline: false) {\n  @include row-between(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-between-stretch()\n///\n@mixin between-stretch($reverse: false, $inline: false) {\n  @include row-between-stretch($reverse, $inline);\n}\n\n@mixin row-around($align: center, $reverse: false, $inline: false) {\n  @include row(space-around, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-around()\n///\n@mixin around($align: center, $reverse: false, $inline: false) {\n  @include row-around($align, $reverse, $inline);\n}\n\n@mixin row-around-stretch($reverse: false, $inline: false) {\n  @include row-around(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-around-stretch()\n///\n@mixin around-stretch($reverse: false, $inline: false) {\n  @include row-around-stretch($reverse, $inline);\n}\n\n@mixin row-evenly($align: center, $reverse: false, $inline: false) {\n  @include row(space-evenly, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-evenly()\n///\n@mixin evenly($align: center, $reverse: false, $inline: false) {\n  @include row-evenly($align, $reverse, $inline);\n}\n\n@mixin row-evenly-stretch($reverse: false, $inline: false) {\n  @include row-evenly(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-evenly-stretch()\n///\n@mixin evenly-stretch($reverse: false, $inline: false) {\n  @include row-evenly-stretch($reverse, $inline);\n}\n\n// columns\n\n@mixin column(\n  $justify: null,\n  $align: null,\n  $reverse: false,\n  $inline: false,\n) {\n  @include -flex(\n    if($reverse, column-reverse, column),\n    $justify,\n    $align,\n    $inline,\n  );\n}\n\n///\n/// @alias column()\n///\n@mixin col(\n  $justify: null,\n  $align: null,\n  $reverse: false,\n  $inline: false,\n) {\n  @include column($justify, $align, $reverse, $inline);\n}\n\n@mixin column-stretch($reverse: false, $inline: false) {\n  @include column(stretch, stretch, $reverse, $inline);\n}\n\n///\n/// @alias column-stretch()\n///\n@mixin col-stretch($reverse: false, $inline: false) {\n  @include column-stretch($reverse, $inline);\n}\n\n@mixin column-start($align: center, $reverse: false, $inline: false) {\n  @include column(flex-start, $align, $reverse, $inline);\n}\n\n///\n/// @alias column-start()\n///\n@mixin col-start($align: center, $reverse: false, $inline: false) {\n  @include column-start($align, $reverse, $inline);\n}\n\n@mixin column-start-stretch($reverse: false, $inline: false) {\n  @include column-start(stretch, $reverse, $inline);\n}\n\n///\n/// @alias column-start-stretch()\n///\n@mixin col-start-stretch($reverse: false, $inline: false) {\n  @include column-start-stretch($reverse, $inline);\n}\n\n@mixin column-center($align: center, $reverse: false, $inline: false) {\n  @include column(center, $align, $reverse, $inline);\n}\n\n///\n/// @alias column-center()\n///\n@mixin col-center($align: center, $reverse: false, $inline: false) {\n  @include column-center($align, $reverse, $inline);\n}\n\n@mixin column-center-stretch($reverse: false, $inline: false) {\n  @include column-center(stretch, $reverse, $inline);\n}\n\n///\n/// @alias column-center-stretch()\n///\n@mixin col-center-st